<?php if($cmsUnavailable):?><p class="notice">Published media is temporarily unavailable. Please return later.</p><?php elseif(!$publicMedia&&!$visibleCollections):?><span class="badge">MEDIA AWAITING APPROVAL</span><h2>Still to be revealed.</h2><p>Official posters, portraits, production stills, behind-the-scenes photography and external teaser links will be collected here when approved.</p><p class="muted">No official film media is published. The homepage illustration is decorative concept artwork, not a production still.</p><?php else:$filter=isset($_GET['collection'])&&is_string($_GET['collection'])?$_GET['collection']:'';?>
<form class="gallery-filter" method="get" action="<?= e(url('media')) ?>"><input type="hidden" name="page" value="media"><label for="collection_filter">Filter media by collection</label><select id="collection_filter" name="collection"><option value="">All collections</option><?php foreach($visibleCollections as $id=>$name):?><option value="<?= (int)$id ?>"<?= $filter===(string)$id?' selected':'' ?>><?= e($name) ?></option><?php endforeach;?></select><button class="button">Filter media</button></form>
<div class="content-grid"><?php $found=false;foreach($publicMedia as $entry):if($filter!==''&&$filter!==(string)$entry['collection_id']){continue;}$found=true;?><article class="content-card"><h2><?= e($entry['title']) ?></h2><?php if($entry['cover_asset_id']):?><figure><a class="gallery-image" href="<?= e(c_media_url((int)$entry['cover_asset_id'],1600)) ?>" data-caption="<?= e($entry['caption'].($entry['credit']?' · '.$entry['credit']:'')) ?>" aria-label="View <?= e($entry['title']) ?> full screen"><img src="<?= e(c_media_url((int)$entry['cover_asset_id'],480)) ?>" srcset="<?= e(c_media_url((int)$entry['cover_asset_id'],480)) ?> 480w, <?= e(c_media_url((int)$entry['cover_asset_id'],960)) ?> 960w" sizes="(max-width: 700px) 90vw, 40vw" width="480" height="320" alt="<?= e($entry['alt_text']) ?>" loading="lazy"></a><figcaption><?= e($entry['caption']) ?><?= $entry['credit']?' · '.e($entry['credit']):'' ?></figcaption></figure><?php endif;?><p><?= e($entry['excerpt']) ?></p><?php if($entry['video_url']):?><a class="text-link" href="<?= e($entry['video_url']) ?>" target="_blank" rel="noopener noreferrer">Watch external video (opens a new tab) →</a><p><?= e($entry['credit']) ?></p><?php endif;?></article><?php endforeach;if(!$found):?><p>No published media matches this collection.</p><?php endif;?></div>
<dialog class="media-viewer" aria-labelledby="viewer_title"><div class="viewer-toolbar"><h2 id="viewer_title">Film image</h2><button type="button" class="button" data-viewer-close>Close</button></div><figure><img alt="" id="viewer_image"><figcaption id="viewer_caption" aria-live="polite"></figcaption></figure><div class="viewer-controls"><button class="button" type="button" data-viewer-prev>Previous image</button><span id="viewer_position" role="status"></span><button class="button" type="button" data-viewer-next>Next image</button></div><p>Use Left/Right arrows to browse, Escape to close, or swipe horizontally.</p></dialog>
<?php endif;?>

<?php if($moreMedia||$publicListPage>1):?><nav class="pager" aria-label="Media pages"><?php if($publicListPage>1):?><a href="<?= e(url('media').'&'.http_build_query(['list_page'=>$publicListPage-1,'collection'=>$collectionFilter])) ?>">← Previous media</a><?php endif;if($moreMedia):?><a href="<?= e(url('media').'&'.http_build_query(['list_page'=>$publicListPage+1,'collection'=>$collectionFilter])) ?>">Next media →</a><?php endif;?></nav><?php endif;?>
